// FilterAdd is a free log retrieval operation binding the contract event 0x9e3d6e2195cad158552215ba6e2ab30995717193c8a61d36f700e6efff8ac244.
//
// Solidity: event Add(string name, address owner, string desc, bytes publicKey, bytes blsPubKey, string hostAddress, uint16 rpcPort, uint16 p2pPort)
func (_Election *ElectionFilterer) FilterAdd(opts *bind.FilterOpts) (*ElectionAddIterator, error) {

	logs, sub, err := _Election.contract.FilterLogs(opts, "Add")
	if err != nil {
		return nil, err
	}
	return &ElectionAddIterator{contract: _Election.contract, event: "Add", logs: logs, sub: sub}, nil
}

// WatchAdd is a free log subscription operation binding the contract event 0x9e3d6e2195cad158552215ba6e2ab30995717193c8a61d36f700e6efff8ac244.
//
// Solidity: event Add(string name, address owner, string desc, bytes publicKey, bytes blsPubKey, string hostAddress, uint16 rpcPort, uint16 p2pPort)
func (_Election *ElectionFilterer) WatchAdd(opts *bind.WatchOpts, sink chan<- *ElectionAdd) (event.Subscription, error) {

	logs, sub, err := _Election.contract.WatchLogs(opts, "Add")
	if err != nil {
		return nil, err
	}
	return event.NewSubscription(func(quit <-chan struct{}) error {
		defer sub.Unsubscribe()
		for {
			select {
			case log := <-logs:
				// New log arrived, parse the event and forward to the user
				event := new(ElectionAdd)
				if err := _Election.contract.UnpackLog(event, "Add", log); err != nil {
					return err
				}
				event.Raw = log

				select {
				case sink <- event:
				case err := <-sub.Err():
					return err
				case <-quit:
					return nil
				}
			case err := <-sub.Err():
				return err
			case <-quit:
				return nil
			}
		}
	}), nil
}

